-- Comentarios da CLT, lote 5 (arts. 171 a 201). Autorizado pela Jessica em 21/10/2026.
-- Redigidos so a partir do texto do artigo e dos dispositivos filhos no banco (sem jurisprudencia ou doutrina).
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='clt' and numero between 171 and 201;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a
from (values
(171,'','Pé-direito dos locais de trabalho','Os locais de trabalho devem ter, no mínimo, 3 (três) metros de pé-direito, assim considerada a altura livre do piso ao teto. O parágrafo único permite reduzir esse mínimo desde que atendidas as condições de iluminação e conforto térmico compatíveis com a natureza do trabalho, sujeitando-se a redução ao controle do órgão competente em matéria de segurança e medicina do trabalho.'),
(172,'','Pisos dos locais de trabalho','Os pisos dos locais de trabalho não devem apresentar saliências nem depressões que prejudiquem a circulação de pessoas ou a movimentação de materiais.'),
(173,'','Aberturas em pisos e paredes','As aberturas nos pisos e paredes são protegidas de forma que impeçam a queda de pessoas ou de objetos.'),
(174,'','Condições de segurança e conservação das áreas de circulação','As paredes, escadas, rampas de acesso, passarelas, pisos, corredores, coberturas e passagens dos locais de trabalho devem obedecer às condições de segurança e de higiene do trabalho estabelecidas pelo Ministério do Trabalho e manter-se em perfeito estado de conservação e limpeza.'),
(175,'','Iluminação dos locais de trabalho','Em todos os locais de trabalho deve haver iluminação adequada, natural ou artificial, apropriada à natureza da atividade. O § 1º exige que a iluminação seja uniformemente distribuída, geral e difusa, a fim de evitar ofuscamento, reflexos incômodos, sombras e contrastes excessivos. O § 2º atribui ao Ministério do Trabalho estabelecer os níveis mínimos de iluminamento a serem observados.'),
(176,'','Ventilação dos locais de trabalho','Os locais de trabalho devem ter ventilação natural, compatível com o serviço realizado. O parágrafo único torna obrigatória a ventilação artificial sempre que a natural não preencha as condições de conforto térmico.'),
(177,'','Proteção contra frio e calor','Se as condições de ambiente se tornarem desconfortáveis, em virtude de instalações geradoras de frio ou de calor, é obrigatório o uso de vestimenta adequada para o trabalho em tais condições ou de capelas, anteparos, paredes duplas, isolamento térmico e recursos similares, de forma que os empregados fiquem protegidos contra as radiações térmicas.'),
(178,'','Limites de conforto térmico','As condições de conforto térmico dos locais de trabalho devem ser mantidas dentro dos limites fixados pelo Ministério do Trabalho.'),
(179,'','Instalações elétricas: normas do Ministério do Trabalho','O Ministério do Trabalho dispõe sobre as condições de segurança e as medidas especiais a serem observadas relativamente a instalações elétricas, em qualquer das fases de produção, transmissão, distribuição ou consumo de energia.'),
(180,'','Profissional qualificado em instalações elétricas','Somente profissional qualificado pode instalar, operar, inspecionar ou reparar instalações elétricas.'),
(181,'','Socorro a acidentados por choque elétrico','Os que trabalharem em serviços de eletricidade ou instalações elétricas devem estar familiarizados com os métodos de socorro a acidentados por choque elétrico.'),
(182,'','Normas sobre movimentação, armazenagem e manuseio de materiais','O Ministério do Trabalho estabelece normas sobre: as precauções de segurança na movimentação de materiais nos locais de trabalho, os equipamentos a serem obrigatoriamente utilizados e as condições especiais a que estão sujeitas a operação e a manutenção desses equipamentos (inciso I); as exigências similares relativas ao manuseio e à armazenagem de materiais, inclusive quanto às condições de segurança e higiene relativas aos recipientes e locais de armazenagem e aos equipamentos de proteção individual (inciso II); e a obrigatoriedade de indicação de carga máxima permitida nos equipamentos de transporte, dos avisos de proibição de fumar e de advertência quanto à natureza perigosa ou nociva à saúde das substâncias em movimentação ou em depósito (inciso III). O parágrafo único aplica as disposições relativas ao transporte de materiais, no que couber, ao transporte de pessoas nos locais de trabalho.'),
(183,'','Métodos de levantamento de cargas','As pessoas que trabalharem na movimentação de materiais devem estar familiarizadas com os métodos racionais de levantamento de cargas.'),
(184,'','Dispositivos de partida e parada em máquinas','As máquinas e os equipamentos devem ser dotados de dispositivos de partida e parada e outros que se fizerem necessários para a prevenção de acidentes do trabalho, especialmente quanto ao risco de acionamento acidental. O parágrafo único proíbe a fabricação, a importação, a venda, a locação e o uso de máquinas e equipamentos que não atendam ao disposto no artigo.'),
(185,'','Reparos, limpeza e ajustes com máquinas paradas','Os reparos, a limpeza e os ajustes somente podem ser executados com as máquinas paradas, salvo se o movimento for indispensável à realização do ajuste.'),
(186,'','Normas adicionais sobre máquinas e equipamentos','O Ministério do Trabalho estabelece normas adicionais sobre proteção e medidas de segurança na operação de máquinas e equipamentos, especialmente quanto à proteção das partes móveis, distância entre estas, vias de acesso às máquinas e equipamentos de grandes dimensões, emprego de ferramentas, sua adequação e medidas de proteção exigidas quando motorizadas ou elétricas.'),
(187,'','Caldeiras e recipientes sob pressão: dispositivos de segurança','As caldeiras, equipamentos e recipientes em geral que operam sob pressão devem dispor de válvula e outros dispositivos de segurança, que evitem seja ultrapassada a pressão interna de trabalho compatível com a sua resistência. O parágrafo único atribui ao Ministério do Trabalho expedir normas complementares quanto à segurança das caldeiras, fornos e recipientes sob pressão, especialmente quanto ao revestimento interno, à localização, à ventilação dos locais e a outros pontos que enumera.'),
(188,'','Inspeção de caldeiras','As caldeiras são periodicamente submetidas a inspeções de segurança, por engenheiro ou empresa especializada, inscritos no Ministério do Trabalho, de conformidade com as instruções expedidas para esse fim. O § 1º exige que toda caldeira seja acompanhada de Prontuário, com documentação original do fabricante, abrangendo, no mínimo, especificação técnica, desenhos, detalhes, provas e testes realizados durante a fabricação e a montagem e características funcionais. O § 2º exige que o proprietário organize, mantenha atualizado e apresente, quando exigido pela autoridade competente, o Registro de Segurança, no qual são anotadas, sistematicamente, as indicações das provas efetuadas, inspeções e reparos. O § 3º submete os projetos de instalação de caldeiras, fornos e recipientes sob pressão à aprovação prévia do órgão regional competente em matéria de segurança do trabalho.'),
(189,'','Conceito de atividades insalubres','São consideradas atividades ou operações insalubres aquelas que, por sua natureza, condições ou métodos de trabalho, exponham os empregados a agentes nocivos à saúde, acima dos limites de tolerância fixados em razão da natureza e da intensidade do agente e do tempo de exposição aos seus efeitos.'),
(190,'','Quadro das atividades insalubres','O Ministério do Trabalho aprova o quadro das atividades e operações insalubres e adota normas sobre os critérios de caracterização da insalubridade, os limites de tolerância aos agentes agressivos, os meios de proteção e o tempo máximo de exposição do empregado a esses agentes. O parágrafo único dispõe que as normas incluem medidas de proteção do organismo do trabalhador nas operações que produzem aerodispersóides tóxicos, irritantes, alérgicos ou incômodos.'),
(191,'','Eliminação ou neutralização da insalubridade','A eliminação ou a neutralização da insalubridade ocorre com a adoção de medidas que conservem o ambiente de trabalho dentro dos limites de tolerância (inciso I) e com a utilização de equipamentos de proteção individual ao trabalhador, que diminuam a intensidade do agente agressivo a limites de tolerância (inciso II). O parágrafo único atribui às Delegacias Regionais do Trabalho, comprovada a insalubridade, notificar as empresas, estipulando prazos para sua eliminação ou neutralização, na forma do artigo.'),
(192,'','Adicional de insalubridade','O exercício de trabalho em condições insalubres, acima dos limites de tolerância estabelecidos pelo Ministério do Trabalho, assegura a percepção de adicional de 40% (quarenta por cento), 20% (vinte por cento) e 10% (dez por cento) do salário-mínimo da região, segundo se classifiquem nos graus máximo, médio e mínimo, respectivamente.'),
(193,'','Atividades perigosas e adicional de periculosidade','São consideradas atividades ou operações perigosas, na forma da regulamentação aprovada pelo Ministério do Trabalho e Emprego, aquelas que, por sua natureza ou métodos de trabalho, impliquem risco acentuado em virtude de exposição permanente do trabalhador a: inflamáveis, explosivos ou energia elétrica (inciso I); roubos ou outras espécies de violência física nas atividades profissionais de segurança pessoal ou patrimonial (inciso II); e colisões, atropelamentos ou outras espécies de acidentes ou violências nas atividades profissionais dos agentes das autoridades de trânsito (inciso III). O § 1º assegura ao empregado em condições de periculosidade adicional de 30% (trinta por cento) sobre o salário sem os acréscimos resultantes de gratificações, prêmios ou participações nos lucros da empresa. O § 2º faculta ao empregado optar pelo adicional de insalubridade que porventura lhe seja devido. O § 3º trata do desconto ou da compensação, do adicional, de outros da mesma natureza eventualmente já concedidos ao vigilante por meio de acordo coletivo. O § 4º considera também perigosas as atividades de trabalhador em motocicleta, e o § 5º afasta a aplicação do inciso I do caput às quantidades de inflamáveis contidas nos tanques de combustíveis originais de fábrica e suplementares, para consumo próprio de veículos de carga e de transporte coletivo de passageiros, nos termos que o parágrafo indica.'),
(194,'','Cessação do adicional de insalubridade ou periculosidade','O direito do empregado ao adicional de insalubridade ou de periculosidade cessa com a eliminação do risco à sua saúde ou integridade física, nos termos da Seção e das normas expedidas pelo Ministério do Trabalho.'),
(195,'','Perícia para caracterização da insalubridade e da periculosidade','A caracterização e a classificação da insalubridade e da periculosidade, segundo as normas do Ministério do Trabalho, far-se-ão através de perícia a cargo de Médico do Trabalho ou Engenheiro do Trabalho, registrados no Ministério do Trabalho. O § 1º faculta às empresas e aos sindicatos das categorias profissionais interessadas requerer ao Ministério do Trabalho a realização de perícia em estabelecimento ou setor deste, com o objetivo de caracterizar e classificar ou delimitar as atividades referidas. O § 2º dispõe que, arguida em juízo insalubridade ou periculosidade, seja por empregado, seja por sindicato em favor de grupo de associados, o juiz designa perito habilitado na forma do artigo e, onde não houver, requisita perícia ao órgão competente do Ministério do Trabalho. O § 3º dispõe que o disposto nos parágrafos anteriores não prejudica a ação fiscalizadora do Ministério do Trabalho, nem a realização de ofício da perícia.'),
(196,'','Efeitos pecuniários da insalubridade e da periculosidade','Os efeitos pecuniários decorrentes do trabalho em condições de insalubridade ou periculosidade são devidos a contar da data da inclusão da respectiva atividade nos quadros aprovados pelo Ministro do Trabalho, respeitadas as normas do art. 11.'),
(197,'','Rotulagem de materiais e substâncias perigosos ou nocivos','Os materiais e substâncias empregados, manipulados ou transportados nos locais de trabalho, quando perigosos ou nocivos à saúde, devem conter, no rótulo, sua composição, recomendações de socorro imediato e o símbolo de perigo correspondente, segundo a padronização internacional. O parágrafo único determina que os estabelecimentos que mantenham as atividades previstas no artigo afixem, nos setores de trabalho atingidos, avisos ou cartazes, com advertência quanto aos materiais e substâncias perigosos ou nocivos à saúde.'),
(198,'','Peso máximo removido individualmente','É de 60 kg (sessenta quilogramas) o peso máximo que um empregado pode remover individualmente, ressalvadas as disposições especiais relativas ao trabalho do menor e da mulher. O parágrafo único exclui da proibição a remoção de material feita por impulsão ou tração de vagonetes sobre trilhos, carros de mão ou quaisquer outros aparelhos mecânicos, podendo o Ministério do Trabalho, em tais casos, fixar limites.'),
(199,'','Assentos para o trabalhador','É obrigatória a colocação de assentos que assegurem postura correta ao trabalhador, capazes de evitar posições incômodas ou forçadas, sempre que a execução da tarefa exija que trabalhe sentado. O parágrafo único dispõe que, quando o trabalho deva ser executado de pé, os empregados têm à sua disposição assentos para serem utilizados nas pausas que o serviço permitir.'),
(200,'','Disposições complementares do Ministério do Trabalho','Cabe ao Ministério do Trabalho estabelecer disposições complementares às normas do Capítulo, tendo em vista as peculiaridades de cada atividade ou setor de trabalho, especialmente sobre: medidas de prevenção de acidentes e equipamentos de proteção individual em obras de construção, demolição ou reparos (inciso I); depósitos, armazenagem e manuseio de combustíveis, inflamáveis e explosivos, bem como trânsito e permanência nas áreas respectivas (inciso II); trabalho em escavações, túneis, galerias, minas e pedreiras (inciso III); proteção contra incêndio em geral e as medidas preventivas adequadas (inciso IV); proteção contra insolação, calor, frio, umidade e ventos, sobretudo no trabalho a céu aberto (inciso V); proteção do trabalhador exposto a substâncias químicas nocivas, radiações ionizantes e não ionizantes, ruídos, vibrações e trepidações ou pressões anormais ao ambiente de trabalho (inciso VI); higiene nos locais de trabalho, com discriminação das exigências, instalações sanitárias, com separação de sexos, chuveiros, lavatórios, vestiários e armários individuais, refeitórios ou condições de conforto por ocasião das refeições (inciso VII); emprego das cores nos locais de trabalho, inclusive nas sinalizações de perigo (inciso VIII); e trabalho realizado em arquivos, em bibliotecas, em museus e em centros de documentação e memória, exposto a agentes patogênicos (inciso IX). O parágrafo único dispõe que, tratando-se de radiações ionizantes e explosivos, as normas são expedidas de acordo com as resoluções adotadas pelo órgão técnico.'),
(201,'','Multas por infração às normas de medicina e segurança do trabalho','As infrações ao disposto no Capítulo relativas à medicina do trabalho são punidas com multa de 3 (três) a 30 (trinta) vezes o valor de referência previsto no art. 2º, parágrafo único, da Lei nº 6.205, de 29 de abril de 1975, e as concernentes à segurança do trabalho com multa de 5 (cinco) a 50 (cinquenta) vezes o mesmo valor. O parágrafo único determina a aplicação da multa em seu valor máximo em caso de reincidência, embaraço ou resistência à fiscalização, emprego de artifício ou simulação com o objetivo de fraudar a lei.')
) as v(n,t,c,a)
where l.codigo='clt' and l.numero=v.n and coalesce(l.titulo,'')=v.t and l.paragrafo is null and l.inciso is null and l.vigente and l.texto ~ '^Art';
